<?php
session_start();

if (!isset($_SESSION["id"])) {
    header("Location: ../../");
    exit();
} else {

    require_once "../../vendor/autoload.php";

    // Create connection
    $conn = new MongoDB\Client("mongodb://localhost:27017");

    // Connecting in database
    $academy = $conn->academy;

    // Connecting in collections
    $users = $academy->users;
    $results = $academy->results;
    $allocations = $academy->allocations;

    // $technician->_id = $_GET["user"];
    $niveau = $_GET["level"];
    // $niveau = "Junior";
    // $numberTest = $_GET["numberTest"];
    $vide = "1";

    // Initialiser les variables pour chaque filiale
    $techniciansCami = [];
    $techniciansGabon = [];
    $techniciansCongo = [];
    $techniciansBenin = [];
    $techniciansBurkina = [];
    $techniciansTogo = [];
    $techniciansTchad = [];
    $techniciansNigeria = [];
    $techniciansNiger = [];
    $techniciansMadagascar = [];
    $techniciansMauritanie = [];
    $techniciansRci = [];
    $techniciansGambie = [];
    $techniciansBissau = [];
    $techniciansEquatorial = [];
    $techniciansGuinee = [];
    $techniciansMali = [];
    $techniciansRca = [];
    $techniciansRdc = [];
    $techniciansSenegal = [];
    $techniciansGhana = [];

    // Définir la liste des filiales
    $subsidiaries = [
        "CAMEROON MOTORS INDUSTRIES" => &$techniciansCami,
        "CFAO MOTORS GABON" => &$techniciansGabon,
        "CFAO MOTORS CONGO" => &$techniciansCongo,
        "CFAO MOTORS BENIN" => &$techniciansBenin,
        "CFAO MOTORS BURKINA" => &$techniciansBurkina,
        "CFAO MOTORS COTE D'IVOIRE" => &$techniciansRci,
        "CFAO (GAMBIA) LIMITED" => &$techniciansGambie,
        "CFAO MOTORS GUINEE BISSAU" => &$techniciansBissau,
        "CFAO MOTORS GUINEE" => &$techniciansGuinee,
        "CFAO MOTORS GUINEA EQUATORIAL" => &$techniciansEquatorial,
        "CFAO MOTORS MALI" => &$techniciansMali,
        "CFAO MOTORS MADAGASCAR" => &$techniciansMadagascar,
        "CFAO MOTORS NIGER" => &$techniciansNiger,
        "CFAO MOTORS CENTRAFRIQUE" => &$techniciansRca,
        "CFAO MOTORS RDC" => &$techniciansRdc,
        "CFAO MOTORS SENEGAL" => &$techniciansSenegal,
        "CFAO MOTORS TCHAD" => &$techniciansTchad,
        "CFAO MOTORS TOGO" => &$techniciansTogo,
        "CFAO MOTORS GHANA" => &$techniciansGhana,
        "CFAO MOTORS NIGERIA" => &$techniciansNigeria,
        "COMPAGNIE MAURITANIENNE DE DISTRIBUTION AUTOMOBILE" => &$techniciansMauritanie
    ];

    // Effectuer une seule requête pour récupérer tous les techniciens et managers actifs dans les filiales spécifiées
    $techniciansAndManagers = $users->find([
        '$and' => [
            ['subsidiary' => ['$in' => array_keys($subsidiaries)]],
            ['active' => true],
            ['$or' => [
                ['profile' => 'Technicien'],
                ['profile' => 'Manager', 'test' => true]
            ]]
        ]
    ])->toArray();

    // Parcourir les techniciens et managers récupérés et les affecter aux bonnes filiales
    foreach ($techniciansAndManagers as $technician) {
        $subsidiary = $technician['subsidiary'];
        if (isset($subsidiaries[$subsidiary])) {
            array_push($subsidiaries[$subsidiary], new MongoDB\BSON\ObjectId($technician['_id']));
        }
    }
    
    include_once "../language.php";

?>

